INSERT INTO academico.enlace_tramite (codigo, nombre, url, descripcion, pasos, palabras_clave) VALUES
('reservas', 'Reservas UNAB', 'https://reservas.unab.edu.co/auth/login', 'Plataforma institucional para reservar espacios, el gimnasio y escenarios deportivos.', '1. Ingresa a la plataforma de reservas con tu cuenta institucional UNAB.
2. Elige el espacio que necesitas (sala de estudio, auditorio, cancha, laboratorio, sala de música o gimnasio).
3. Selecciona la fecha y la franja horaria disponible.
4. Confirma la reserva. Si el espacio tiene tarifa, el sistema te indica cómo pagar; las salas de estudio y el gimnasio son gratis.
5. Revisa tu correo UNAB: allí llega la confirmación.', ARRAY['reserva', 'reservar', 'espacio', 'sala', 'salas de estudio', 'auditorio', 'cancha', 'laboratorio', 'sala de música', 'escenario deportivo']::text[]),
('biblioteca_renovar', 'Renovar préstamos de biblioteca', 'https://catalogo.unab.edu.co/', 'Catálogo de la Biblioteca UNAB. Es el enlace del QR del cartel "Renueva tus préstamos y evita sanciones".', '1. Escanea el código QR del cartel "Renueva tus préstamos y evita sanciones" o abre el enlace del catálogo.
2. Inicia sesión con tu cuenta UNAB.
3. Entra a "Mi cuenta" y abre la lista de tus préstamos.
4. Selecciona el material y pulsa "Renovar" antes de la fecha de vencimiento.
5. Si el préstamo ya venció, la multa es de $1.500 COP por día de retraso y debes pagarla antes de renovar.', ARRAY['biblioteca', 'renovar', 'renovación', 'préstamo', 'prestamo', 'libro', 'multa', 'sanción', 'devolver', 'catálogo']::text[]),
('gimnasio', 'Gimnasio (Bienestar Universitario)', 'https://reservas.unab.edu.co/auth/login', 'El gimnasio se reserva en la misma plataforma de reservas; es gratis para estudiantes.', '1. Ingresa a la plataforma de reservas con tu cuenta institucional UNAB.
2. Busca el espacio "Gimnasio".
3. Escoge el día y la franja horaria con cupo.
4. Confirma la reserva; no tiene costo para estudiantes activos.
5. Llega 10 minutos antes con tu carné y ropa deportiva.', ARRAY['gimnasio', 'gym', 'ejercicio', 'deporte', 'bienestar', 'entrenar', 'pesas']::text[]),
('cosmos', 'Cosmos', 'https://cosmos.unab.edu.co/', 'Sistema académico: notas por corte, horario, historial y datos de matrícula.', '1. Ingresa a Cosmos con tu usuario y contraseña institucionales.
2. En "Notas" consulta las calificaciones por corte (30 %, 30 % y 40 %) del periodo actual.
3. En "Horario" revisa tus clases, salones y docentes.
4. En "Historial" descarga tu registro de notas y créditos aprobados.', ARRAY['cosmos', 'notas', 'calificaciones', 'corte', 'horario', 'historial', 'matrícula', 'créditos']::text[]),
('tema', 'TEMA', 'https://tema.unab.edu.co/', 'Plataforma virtual de cursos: tareas, quices, foros y materiales de cada asignatura.', '1. Ingresa a TEMA con tu cuenta institucional.
2. Abre el curso (sección) que quieres revisar.
3. En el calendario o en cada curso verás las tareas, quices y foros con su fecha de entrega.
4. Sube tu entrega antes de la fecha límite (23:59) y verifica que quede en estado "entregada".', ARRAY['tema', 'tarea', 'tareas', 'quiz', 'foro', 'entrega', 'aula virtual', 'plataforma', 'moodle']::text[]),
('evaluacion_docente', 'Evaluación docente', 'https://tema.unab.edu.co/', 'Calificación anónima de tus profesores al final del periodo. Se hace desde TEMA (o Cosmos).', '1. Ingresa a TEMA (https://tema.unab.edu.co/) o a Cosmos (https://cosmos.unab.edu.co/) con tu cuenta institucional.
2. Abre la opción "Evaluación docente".
3. Selecciona cada profesor pendiente y responde el cuestionario.
4. Envía la evaluación antes de la fecha límite (2026-11-28 en 2026-2). Es anónima.', ARRAY['evaluación docente', 'evaluacion docente', 'calificar al profesor', 'calificar profesor', 'encuesta docente', 'evaluar docente']::text[]),
('unab', 'Portal UNAB', 'https://unab.edu.co', 'Portal principal de la Universidad Autónoma de Bucaramanga.', '1. Ingresa al portal principal de la UNAB.
2. Usa el buscador o el menú para encontrar programas, calendario académico, bienestar y servicios.
3. Para trámites con usuario, entra a Cosmos, TEMA o la plataforma de reservas con tu cuenta institucional.', ARRAY['unab', 'portal', 'universidad', 'información general', 'página web', 'contacto']::text[])
ON CONFLICT DO NOTHING;

INSERT INTO academico.persona_demo (codigo, titulo, descripcion, emoji, orden) VALUES
('U00000001', 'Laura · Sistemas · semestre 6', 'Semestre 6, promedio 3.6 y 52 % de avance, con 4 cursos reprobados (p. ej. Estadística General). Pregúntale cómo recuperarlos y qué le falta para avanzar.', '🧑‍💻', 1),
('U00000201', 'Santiago · Sistemas · casi graduado', 'Pregúntale qué requisitos de grado le faltan y qué necesita para graduarse.', '🎓', 2),
('U00000202', 'Valentina · Medicina · en riesgo', 'Pregúntale por su riesgo académico y sus tareas vencidas.', '🩺', 3),
('U00000203', 'Juan Camilo · Derecho · cerca del grado', 'Pregúntale cuántos semestres le quedan y qué requisitos de grado tiene pendientes.', '⚖️', 4),
('U00000204', 'Sofía · Psicología · primer semestre', 'Pregúntale por su horario, el calendario y cómo moverse en la universidad.', '🧠', 5),
('U00000205', 'Andrés Felipe · Administración · matrícula pendiente', 'Pídele pagar su matrícula 2026-2 con Bold (modo pruebas).', '💼', 6),
('U00000206', 'Nicolás · Mecatrónica · multa de biblioteca', 'Pregúntale por su préstamo vencido: renovar en el catálogo y pagar la multa.', '🤖', 7)
ON CONFLICT DO NOTHING;

